const upsertProjectImportChunk = `-- name: UpsertProjectImportChunk :exec
INSERT INTO project_import_chunk (workspace_id, import_id, chunk_index, bytes, storage_key)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (workspace_id, import_id, chunk_index) DO UPDATE SET bytes = excluded.bytes
`

type UpsertProjectImportChunkParams struct {
	WorkspaceID pgtype.UUID
	ImportID    pgtype.UUID
	ChunkIndex  int32
	Bytes       int32
	StorageKey  string
}

// UpsertProjectImportChunk records that the chunk is stored, or that it was
// stored again, as a resumed upload may send it.
func (q *Queries) UpsertProjectImportChunk(ctx context.Context, arg UpsertProjectImportChunkParams) error {
	_, err := q.db.Exec(ctx, upsertProjectImportChunk,
		arg.WorkspaceID,
		arg.ImportID,
		arg.ChunkIndex,
		arg.Bytes,
		arg.StorageKey,
	)
	return err
}

const workspaceMembersAmong = `-- name: WorkspaceMembersAmong :many
SELECT m.user_id FROM membership m JOIN "user" u ON u.id = m.user_id
WHERE m.workspace_id = $1 AND m.user_id = ANY($2::uuid[]) AND u.status = 'active'
`

type WorkspaceMembersAmongParams struct {
	WorkspaceID pgtype.UUID
	UserIds     []pgtype.UUID
}

// WorkspaceMembersAmong returns those of the users who are members of the
// workspace with an active account, whom an imported archive's names keep.
func (q *Queries) WorkspaceMembersAmong(ctx context.Context, arg WorkspaceMembersAmongParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, workspaceMembersAmong, arg.WorkspaceID, arg.UserIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var user_id pgtype.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
